<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/student_portal.php';$current=tuman_require_role('STUDENT');$db=tuman_database();$assignments=tuman_student_teacher_assignments($db,$current['id']);try{$assignmentId=tuman_student_owned_assignment_id($db,$current['id'],$_GET['assignment_id']??null);$payments=tuman_student_payments($db,$current['id'],$assignmentId);}catch(InvalidArgumentException $e){http_response_code(404);exit('Payments unavailable.');}tuman_student_page_start('My payments');
?>
<h1>My payments</h1><form method="get"><p><label>Teacher <select name="assignment_id"><option value="">All my Teachers</option><?php foreach($assignments as $assignment): ?><option value="<?= (int)$assignment['assignment_id'] ?>"<?= $assignmentId===(int)$assignment['assignment_id']?' selected':'' ?>><?= htmlspecialchars(trim($assignment['first_name'].' '.($assignment['last_name']??'')),ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><button>View</button></p></form><p>Payment history is read-only. Voided payments remain visible.</p><div style="overflow-x:auto"><table><thead><tr><th>Teacher</th><th>Invoice</th><th>Date</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= htmlspecialchars(trim($payment['teacher_first_name'].' '.($payment['teacher_last_name']??'')),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['invoice_number'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(tuman_invoice_money_label($payment['amount'],$payment['currency_code']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_method'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['status'],ENT_QUOTES,'UTF-8') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($payments===[]): ?><p>No payments are available.</p><?php endif; ?><?php tuman_student_page_end(); ?>
